metaData.script:
function check() {
	var action = workflowData.getMetaDataMap().get("actionTakenByTimeKeeper");   
	log.info("action by employee:" + action);
    if ((action == "Send Back to Requestor")) {        
        return true;
    }
    else {
        return false;
    }
}

